/* Studio editorial: distinct from the exploratory Lab; interface captures from Catalisa's public site. */
const S_PROFILE_SHOTS=[{"file":"studio-service-manual.png","title":"Formulário / Prepare o perfil passo a passo","desc":"Defina finalidade, apoio, ações e revisão pelo formulário.","type":"Preparação pelo formulário","origin":"20/10/2026 · prévia local de integração · formulário manual","product":"studio-profiles","path":"docs/analysis/2026-10-20-crm-integracao/screenshots/panel-wizard-purpose.png","sha":"23e4f2ef22da7715c1a96b05f9e138137716d89d","source":"https://github.com/catalisaio/wpp.bb.catalisa.io/blob/3fc7b15c9b16107d16770bf6412e99e957315681/docs/analysis/2026-10-20-crm-integracao/screenshots/panel-wizard-purpose.png"},{"file":"studio-service-ai.png","title":"Com IA / Comece pelo resultado esperado","desc":"Descreva o trabalho e prepare uma configuração para revisão com apoio do assistente.","type":"Preparação com apoio de IA","origin":"20/10/2026 · candidato local de design · tela anterior ao início da IA","product":"studio-profiles","path":"docs/analysis/2026-10-20-crm-validacao/visible-design-admin-2026-10-20T22-45-07-396Z/local-cta-prepare-start-reachable-1280.png","sha":"b060171b78cb2a3e37bb42d0fe98fba27d5d4355","source":"https://github.com/catalisaio/wpp.bb.catalisa.io/blob/3fc7b15c9b16107d16770bf6412e99e957315681/docs/analysis/2026-10-20-crm-validacao/visible-design-admin-2026-10-20T22-45-07-396Z/local-cta-prepare-start-reachable-1280.png"}];
Object.assign(X_CAPTURE_META,Object.fromEntries(S_PROFILE_SHOTS.map(s=>[s.file,s])));
const S_STAGES=[
{title:'Descreva a necessidade.',tag:'01 / A intenção',copy:'Comece pelo trabalho que precisa acontecer: quem participa, o que inicia a jornada e qual próximo passo você espera.',quote:'“Quando chegar uma nova mensagem, entenda o pedido, avise a equipe e mantenha o atendimento organizado.”',output:'Uma necessidade com contexto.',shape:'intention'},
{title:'Revise o plano.',tag:'02 / A especificação',copy:'A descrição ganha estrutura. Confira as informações necessárias, as ferramentas envolvidas e os limites antes de seguir.',quote:'Quem recebe a mensagem? Que informação pode ser consultada? Quando uma pessoa precisa assumir?',output:'Um plano que o time consegue discutir.',shape:'plan'},
{title:'Conecte as capacidades.',tag:'03 / A composição',copy:'O fluxo visual mostra como as ações se relacionam. Conhecimento, canais e Building Blocks entram conforme a necessidade da jornada.',quote:'A entrada encontra o contexto. A regra orienta o caminho. A ferramenta realiza a ação.',output:'Um percurso legível, com responsabilidades.',shape:'compose'},
{title:'Valide e acompanhe.',tag:'04 / A operação',copy:'Teste o comportamento, confira as permissões e acompanhe o resultado. O que a operação ensina orienta o próximo ajuste.',quote:'O que aconteceu? Onde a equipe precisou intervir? O que deve mudar na próxima versão?',output:'Uma base para observar e evoluir.',shape:'operate'}
];
const S_CASES=[
{label:'Atendimento',title:'O pedido chega.<br>A equipe encontra contexto.',intro:'Uma mensagem deixa de ser apenas uma conversa isolada e passa a participar do trabalho.',start:'Nova mensagem',middle:'Entender o pedido',branches:['Orientar o cliente','Encaminhar à equipe'],end:'Registrar continuidade',copy:'O Studio ajuda a estruturar a resposta e as ações que acompanham a conversa. A equipe define o que pode ser respondido, quais informações podem ser usadas e quando o atendimento precisa de uma pessoa.',blocks:[['wpp-business','Canal oficial'],['ai-engine','Leitura do contexto'],['customers','Relacionamento']],note:'Exemplo ilustrativo. Políticas do canal, autorizações e tratamento de exceções fazem parte da configuração.'},
{label:'Crédito',title:'A proposta avança.<br>A política mantém seu lugar.',intro:'Preparar o contexto, avaliar a regra e encaminhar o próximo passo são responsabilidades diferentes.',start:'Proposta recebida',middle:'Preparar informações',branches:['Consultar a política','Revisar pendências'],end:'Encaminhar o resultado',copy:'A composição organiza as etapas e as capacidades necessárias. A política permanece explícita; a equipe define os critérios, a revisão e os limites da operação.',blocks:[['decision-platform','Preparação da análise'],['decision-engine','Política de decisão'],['e-signature','Formalização']],note:'Exemplo ilustrativo. Disponibilidade das integrações e validação da operação precisam ser confirmadas antes do uso.'},
{label:'Relacionamento',title:'Uma nova pessoa.<br>Um começo com continuidade.',intro:'Receber, dar boas-vindas e avisar a equipe podem fazer parte da mesma jornada.',start:'Novo contato',middle:'Preparar boas-vindas',branches:['Enviar mensagem','Avisar a equipe'],end:'Atualizar o relacionamento',copy:'Um ponto de partida do Builder pode ser ajustado ao contexto da empresa. O time revisa a mensagem, o canal, os dados usados e o que acontece depois da primeira interação.',blocks:[['customers','Cadastro do contato'],['wpp-business','Boas-vindas'],['email','Notificação à equipe']],note:'Exemplo ilustrativo baseado nos pontos de partida apresentados pelo Studio. Envio depende das permissões e regras do canal.'}
];
S_CASES.push(
{label:'Banking',title:'O cliente vê uma conta.<br>A operação conecta a base.',intro:'Saldo, movimentação e confirmação encontram uma jornada comum entre aplicativo e operação.',start:'Cliente acessa a conta',middle:'Identificar e dar contexto',branches:['Consultar a conta','Autorizar a operação'],end:'Apresentar o resultado',copy:'O Studio ajuda a organizar como a experiência usa identidade, serviços bancários e confirmação do titular. O aplicativo apresenta o próximo passo; as capacidades responsáveis aplicam suas regras e devolvem o resultado.',blocks:[['iam','Identidade e permissões'],['baas','Conta e movimentação'],['biometrics','Confirmação do titular']],note:'Leitura conceitual. Serviços bancários dependem de parceiro contratado e integrações validadas. A confirmação exigida varia conforme a operação.'},
{label:'Copiloto',title:'A pessoa conduz.<br>O contexto acompanha.',intro:'Um perfil reúne o objetivo da conversa, o apoio ao profissional e os próximos passos do atendimento.',start:'Atendimento iniciado',middle:'Reunir o contexto autorizado',branches:['Sugerir durante a conversa','Preparar resumo ao encerrar'],end:'Revisar e dar continuidade',copy:'O profissional define o que o copiloto deve observar e quais ações podem acontecer em cada momento. Sugestões apoiam a conversa; documentos e próximos passos podem passar por revisão antes de seguir para a operação.',blocks:[['rooms','Encontro e contexto'],['ai-engine','Apoio à interpretação'],['data-store','Continuidade do atendimento']],note:'Exemplo ilustrativo. Apoio de IA, resumo e automações são escolhas independentes; disponibilidade, autorização e revisão são definidas no perfil.'}
);
const S_SHOTS=[
{file:'studio-builder.jpg',title:'Builder / A descrição é o ponto de partida',desc:'A tela reúne a descrição da necessidade e exemplos para iniciar a construção.',type:'Builder',source:'https://catalisa.io/screenshots/studio/builder-home-real.jpg'},
{file:'studio-canvas.png',title:'Canvas / As conexões ficam visíveis',desc:'O editor apresenta ações e ramificações de um fluxo no espaço visual.',type:'Canvas',source:'https://catalisa.io/screenshots/workflow-editor.png'},
{file:'studio-dashboard.jpg',title:'Painel / O trabalho ganha uma visão comum',desc:'O painel reúne a leitura de contatos, mensagens e workflows da operação.',type:'Painel',source:'https://catalisa.io/screenshots/dashboard.jpeg'}
];
Object.assign(X_CAPTURE_META,Object.fromEntries(S_SHOTS.map(s=>[s.file,{...s,product:'studio',origin:'Captura publicada no site Catalisa · consultada em 22/10/2026 · data original não informada'}])));
function sSculpture(){return `<svg class="s-sculpture" viewBox="0 0 740 620" role="img" aria-label="Uma intenção ganha estrutura: planos de projeto se encontram em um percurso laranja"><defs><linearGradient id="studio-paper" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e4d8ee"/><stop offset="1" stop-color="#b79bcb"/></linearGradient><linearGradient id="studio-arch"><stop stop-color="#ffba75"/><stop offset="1" stop-color="#df7836"/></linearGradient><filter id="studio-shadow"><feGaussianBlur stdDeviation="13"/></filter></defs><ellipse cx="385" cy="496" rx="224" ry="40" fill="#4a2c60" opacity=".1" filter="url(#studio-shadow)"/><g stroke="#c5b4d0" stroke-width=".7" fill="none"><path d="M45 423L363 238L689 426L371 610Z"/><path d="M115 462L433 277M187 504L505 319M262 547L580 362M111 385L438 574M185 342L511 531M260 299L586 488" stroke-dasharray="3 7"/></g><g class="s-plane-back"><path d="M235 185L448 62L635 171L422 294Z" fill="#f0e8f5"/><path d="M235 185V204L422 313V294Z" fill="#cbb6da"/><path d="M422 294L635 171V190L422 313Z" fill="#a484bb"/><g stroke="#b39ac4" stroke-width="1" fill="none"><path d="M310 184L450 103L560 167M345 205L451 144L525 187M380 226L451 185L490 208"/></g></g><g class="s-plane-front"><path d="M122 335L335 212L522 321L309 444Z" fill="url(#studio-paper)"/><path d="M122 335V365L309 474V444Z" fill="#a586bd"/><path d="M309 444L522 321V351L309 474Z" fill="#71468d"/><path d="M184 335L335 248L457 319L306 406Z" stroke="#f4eef7" stroke-width="1" fill="none"/><path d="M225 335L335 272L417 319" stroke="#8a63a5" stroke-width="1" fill="none"/></g><g class="s-orange-route"><path d="M344 339V224C344 166 394 137 444 166L504 201V241L444 206C418 191 390 208 390 238V366Z" fill="url(#studio-arch)"/><path d="M390 366L411 354V244C411 224 427 216 444 226L504 261V241L444 206C418 191 390 208 390 238Z" fill="#be612f"/><path d="M344 339L366 352L411 379L390 392Z" fill="#ed934e"/></g><g stroke="#9b7eaf" fill="none"><path d="M144 130V93H224M550 422H605V342"/><circle cx="144" cy="143" r="4"/><circle cx="605" cy="329" r="4"/></g><g fill="#f4c53a"><circle cx="167" cy="433" r="12"/><circle cx="562" cy="255" r="6"/></g><text x="77" y="555" fill="#aa92b8" font-size="9" font-family="monospace" letter-spacing="2">INTENÇÃO / ESTRUTURA / CONTINUIDADE</text></svg>`}
function sStageArt(i){const labels=[['Uma necessidade','Pessoas + contexto','Próximo passo'],['Objetivo','Informações','Limites'],['Entrada','Capacidades','Resultado'],['Observar','Revisar','Evoluir']][i];return `<svg viewBox="0 0 660 390" class="s-stage-art" role="img" aria-label="${ce(labels.join(', '))}"><g fill="none" stroke="#b39ac5"><path d="M95 215C180 215 175 105 285 105S385 275 470 275H565" stroke-width="2"/><path class="s-current" d="M95 215C180 215 175 105 285 105S385 275 470 275H565" stroke="#ed995d" stroke-width="4" stroke-dasharray="6 22"/></g>${[[105,215],[300,110],[535,275]].map(([x,y],j)=>`<g><circle cx="${x}" cy="${y}" r="${j===i%3?42:31}" fill="${j===i%3?'#efaa70':'#76508f'}"/><circle cx="${x}" cy="${y}" r="${j===i%3?56:43}" fill="none" stroke="#bca1ce" stroke-width=".7"/><text x="${x}" y="${y+5}" text-anchor="middle" font-family="monospace" font-size="13" fill="#fff8f0">0${j+1}</text><text x="${x}" y="${y+83}" text-anchor="middle" fill="#8f759d" font-family="Inter,sans-serif" font-size="12">${labels[j]}</text></g>`).join('')}</svg>`}
function sStagePanel(i){const s=S_STAGES[i];return `<div class="s-stage-copy"><span class="label">${s.tag}</span><h3>${s.title}</h3><p>${s.copy}</p><blockquote>${s.quote}</blockquote><span class="s-stage-result">${s.output}</span></div><div class="s-stage-visual">${sStageArt(i)}<span>Leitura conceitual do processo de construção</span></div>`}
function sCapture(i){const s=S_SHOTS[i];return `<div class="s-capture-frame"><div class="s-capture-bar"><span><i></i><i></i><i></i></span><span>${s.type} / Catalisa Studio</span><small>Ampliar ↗</small></div><button data-gallery-file="${s.file}" data-gallery-product="studio" aria-label="Ampliar captura do ${s.type}"><img src="/assets/screens/${s.file}" alt="${ce(s.title)}" loading="lazy" width="${i===0?1920:1600}" height="${i===0?1013:i===1?870:900}"></button><div class="s-capture-caption"><p>${s.desc}</p><a href="${s.source}" target="_blank" rel="noopener">Origem da captura ↗</a></div></div>`}
function sExampleArt(c){return `<svg viewBox="0 0 640 465" role="img" aria-label="${ce(c.start+', '+c.middle+', '+c.branches.join(' e ')+', '+c.end)}"><g fill="none" stroke="#9470ac" stroke-width="1.2"><path d="M320 83V126M320 189V221H165V254M320 221H475V254M165 317V357H320V383M475 317V357H320"/><path class="s-current" d="M320 83V126M320 189V221H165V254M320 221H475V254M165 317V357H320V383M475 317V357H320" stroke="#f1b575" stroke-width="2" stroke-dasharray="3 15"/></g>${[[210,25,220,58,c.start,'#e9dff0'],[195,128,250,60,c.middle,'#9a77b5'],[55,256,220,60,c.branches[0],'#e8a36b'],[365,256,220,60,c.branches[1],'#e9dff0'],[175,385,290,58,c.end,'#9a77b5']].map(([x,y,w,h,t,f],i)=>`<g><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${i===0||i===4?29:3}" fill="${f}"/><text x="${x+w/2}" y="${y+h/2+5}" text-anchor="middle" font-size="13" font-family="Inter,sans-serif" fill="${i===1||i===4?'#fff8ff':'#493058'}">${ce(t)}</text></g>`).join('')}</svg>`}
function sExample(i){const c=S_CASES[i];return `<div class="s-example-drawing">${sExampleArt(c)}<span>Uma leitura da jornada / ${c.label}</span></div><div class="s-example-copy"><span class="label">Uma composição possível</span><h3>${c.title}</h3><p>${c.intro}</p><p>${c.copy}</p><div class="s-example-blocks">${c.blocks.map(([slug,n])=>`<a href="/capacidades/${slug}/">${n} <span>↗</span></a>`).join('')}</div><small>${c.note}</small></div>`}
function sPage(){return `<div class="s-page"><section class="s-hero"><div class="wrap"><div class="s-hero-copy"><span class="label">Catalisa Studio / Construir por composição</span><h1>Dê forma<br>ao que precisa<br><em>funcionar.</em></h1><p>Da descrição do trabalho às conexões que o realizam. Um espaço para estruturar agentes, organizar automações e evoluir a operação.</p><a class="text-link" href="#construir">Veja como se constrói <span>↓</span></a></div><div class="s-hero-sculpture">${sSculpture()}</div></div><div class="s-hero-foot wrap"><span>Descrever é o começo.<br>Entender as conexões é construir.</span><button class="s-motion-button" data-s-motion aria-pressed="false">Ⅱ Pausar movimento</button></div></section><section class="s-purpose wrap"><span class="label">O que é o Studio</span><h2>A ideia encontra<br>um plano.<br><em>O plano encontra as peças.</em></h2><div><p>O Studio é o espaço de construção da Catalisa. A necessidade é descrita, ganha uma especificação para revisão e se conecta a ferramentas e fluxos visuais.</p><p>O time de negócio traz o contexto. Quem constrói traduz esse contexto em uma jornada. A plataforma oferece capacidades que podem ser combinadas em vez de recomeçar cada parte.</p><p class="s-purpose-line">O valor está em tornar o trabalho compreensível antes de ampliar a automação.</p></div></section><section class="s-build" id="construir"><div class="wrap"><div class="s-section-heading"><div><span class="label">Da intenção à operação</span><h2>Construir também<br>é fazer boas perguntas.</h2></div><p>Explore o percurso.<br>Cada etapa deixa uma decisão mais clara.</p></div><div class="s-stage-tabs" role="tablist" aria-label="Etapas da construção">${['Descrever','Revisar','Conectar','Acompanhar'].map((x,i)=>`<button role="tab" data-s-stage="${i}" id="s-stage-tab-${i}" aria-controls="s-stage-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}"><span>0${i+1}</span>${x}<i aria-hidden="true">↗</i></button>`).join('')}</div><div id="s-stage-panel" role="tabpanel" aria-labelledby="s-stage-tab-0" class="s-stage-panel">${sStagePanel(0)}</div></div></section><section class="s-interface"><div class="wrap"><div class="s-interface-heading"><div><span class="label">Dentro do Studio</span><h2>O trabalho ganha<br>um lugar para acontecer.</h2></div><p>Descrever, conectar e acompanhar.<br>Três leituras da interface da plataforma.</p></div><div class="s-interface-tabs" role="tablist" aria-label="Interfaces do Studio">${S_SHOTS.map((s,i)=>`<button role="tab" id="s-capture-tab-${i}" data-s-capture="${i}" aria-controls="s-capture-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}"><span>0${i+1}</span>${s.type}</button>`).join('')}</div><div class="s-capture-exhibition"><div class="s-exhibition-orbit" aria-hidden="true"></div><div id="s-capture-panel" role="tabpanel" aria-labelledby="s-capture-tab-0">${sCapture(0)}</div></div><div class="s-interface-note"><p>Capturas publicadas no site da Catalisa, consultadas em 22/10/2026. A data original não é informada. As telas são referências da interface, não uma demonstração ao vivo nem indicadores de clientes.</p>${ca('https://catalisa.io/studio/','Referência do Studio')}</div></div></section><section class="s-examples wrap"><div class="s-section-heading"><div><span class="label">A construção encontra o negócio</span><h2>O mesmo espaço.<br>Trabalhos diferentes.</h2></div><p>Troque o contexto para explorar<br>o que a composição organiza.</p></div><div class="s-example-tabs" role="tablist" aria-label="Contextos de uso">${S_CASES.map((c,i)=>`<button role="tab" id="s-example-tab-${i}" data-s-case="${i}" aria-controls="s-example-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${c.label}</button>`).join('')}</div><div id="s-example-panel" class="s-example-panel" role="tabpanel" aria-labelledby="s-example-tab-0">${sExample(0)}</div></section>${sProfilesSection()}<section class="s-responsibility"><div class="wrap"><div class="s-responsibility-title"><span class="label">Clareza antes de autonomia</span><h2>Uma boa automação<br>sabe onde<br><em>pedir uma pessoa.</em></h2><p>Definir o que a jornada pode fazer é tão importante quanto conectar suas ações.</p>${ca('/governanca/','Explore a governança')}</div><div class="s-checks">${[['Contexto','Qual problema estamos resolvendo? Que informações podem entrar nessa conversa?'],['Acesso','Quais ferramentas a jornada pode usar? Quem tem permissão para consultar ou alterar?'],['Revisão','Que ação precisa de aprovação? O que acontece quando falta uma informação?'],['Continuidade','Como a equipe acompanha o resultado, entende uma exceção e retoma o atendimento?']].map(([t,p],i)=>`<article><span>0${i+1}</span><div><h3>${t}</h3><p>${p}</p></div></article>`).join('')}</div></div></section><section class="s-paths wrap"><span class="label">Encontre o próximo passo</span><div class="s-paths-heading"><h2>Explorar, construir<br>e executar se conectam.</h2><p>Cada espaço ajuda em uma parte do caminho.</p></div><div class="s-path-comparison"><a href="/lab/"><span>01 / Imaginar</span><h3>Lab</h3><p>Dar uma primeira forma à ideia e conversar sobre o produto que você quer criar.</p><small>Explore uma possibilidade ↗</small></a><div class="s-path-current"><span>02 / Construir</span><h3>Studio</h3><p>Estruturar a necessidade, revisar o plano e compor as capacidades da jornada.</p><small>Você está aqui</small></div><a href="/workflows/"><span>03 / Conectar a operação</span><h3>Workflows</h3><p>Entender como eventos, condições e ações organizam o que acontece em seguida.</p><small>Entenda os fluxos ↗</small></a></div></section><section class="s-questions wrap"><div><span class="label">Antes de começar</span><h2>Menos dúvida.<br>Mais direção.</h2><p>Comece com uma jornada delimitada e valide o comportamento antes de ampliar.</p></div><div>${[
['Preciso começar do zero?','Você pode descrever uma necessidade ou partir dos exemplos do Builder, como boas-vindas, notificação e relacionamento. O ponto de partida deve ser ajustado ao contexto e às regras da sua operação.'],
['O que preciso saber para descrever a ideia?','Explique quem participa, o que inicia o trabalho, quais informações são necessárias e como seria um bom resultado. Diga também quando uma pessoa deve revisar ou assumir a conversa.'],
['O Studio substitui as capacidades da plataforma?','O Studio ajuda a estruturar a construção. Os Building Blocks oferecem as capacidades; os workflows organizam as ações; as integrações conectam os sistemas necessários. São partes que trabalham em conjunto.'],
['A IA pode decidir tudo sozinha?','O papel da IA e os limites da jornada precisam ser definidos. Regras de negócio, permissões, decisões importantes e revisão humana devem estar explícitas. A composição precisa respeitar essas responsabilidades.'],
['Uma integração aparece na tela. Posso usá-la imediatamente?','A disponibilidade depende da capacidade, do estágio, das credenciais e dos contratos necessários. Consulte a documentação e valide o fluxo completo antes de planejar o uso em produção.'],
['Como começo a avaliar o Studio?','Escolha um problema recorrente e fácil de observar. Descreva o caminho atual, os participantes e o resultado esperado. Use o Lab para explorar a ideia ou converse com a Catalisa para avaliar a construção.']
].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">＋</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="s-closing"><div class="wrap"><span class="label">Uma base para o próximo movimento</span><h2>Seu próximo produto<br>pode começar<br>com uma boa descrição.</h2><div>${ca('/lab/','Imagine seu produto no Lab')}${ca('/contato/','Converse sobre o Studio')}</div><span class="s-closing-sigil" aria-hidden="true"></span></div></section></div>`}
const sOriginalPage=cPage;cPage=function(route,blocks){return route==='/studio/'?sPage():sOriginalPage(route,blocks)};
function sBind(){const root=document.querySelector('.s-page');if(!root)return;const bindTabs=(selector,render,panelId,prefix)=>{const tabs=[...root.querySelectorAll(selector)];tabs.forEach((b,i)=>{b.addEventListener('click',()=>{tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});const panel=document.getElementById(panelId);panel.innerHTML=render(i);panel.setAttribute('aria-labelledby',prefix+i)});b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();tabs[n].focus()})})};bindTabs('[data-s-stage]',sStagePanel,'s-stage-panel','s-stage-tab-');bindTabs('[data-s-case]',sExample,'s-example-panel','s-example-tab-');
// Keep the same image trigger alive so the shared, accessible gallery retains its event binding.
const captureTabs=[...root.querySelectorAll('[data-s-capture]')];captureTabs.forEach((b,i)=>{b.addEventListener('click',()=>{captureTabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});const panel=document.getElementById('s-capture-panel'),s=S_SHOTS[i],image=panel.querySelector('img'),trigger=panel.querySelector('[data-gallery-file]');trigger.dataset.galleryFile=s.file;trigger.setAttribute('aria-label','Ampliar captura do '+s.type);image.src='/assets/screens/'+s.file;image.alt=s.title;image.removeAttribute('height');image.removeAttribute('width');panel.querySelector('.s-capture-bar>span:nth-child(2)').textContent=s.type+' / Catalisa Studio';panel.querySelector('.s-capture-caption>p').textContent=s.desc;panel.querySelector('.s-capture-caption>a').href=s.source;panel.setAttribute('aria-labelledby',b.id)});b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?captureTabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+captureTabs.length)%captureTabs.length;captureTabs[n].click();captureTabs[n].focus()})});root.querySelector('[data-s-motion]').addEventListener('click',e=>{const paused=root.classList.toggle('s-motion-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'▶ Retomar movimento':'Ⅱ Pausar movimento'})}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',sBind);
function sProfilesSection(){return `<section class="s-profiles" id="perfis"><div class="wrap"><div class="s-profiles-heading"><div><span class="label">Perfis de atendimento / Dois caminhos para preparar</span><h2>Seu jeito de atender.<br>Com o apoio que faz sentido.</h2></div><p>Configure o perfil pelo formulário ou use a IA para ajudar a preparar. A finalidade continua sendo sua; a revisão também.</p></div><div class="s-profile-comparison">${S_PROFILE_SHOTS.map((s,i)=>`<article class="s-profile-method s-profile-method-${i}"><div class="s-profile-method-title"><span>0${i+1} / ${i?'Com apoio de IA':'Sem IA na preparação'}</span><h3>${i?'Conte o resultado.<br>Revise a proposta.':'Defina cada parte.<br>No seu ritmo.'}</h3><p>${i?'Descreva o trabalho que precisa acontecer. O assistente ajuda a planejar recursos e vínculos para você revisar antes de aprovar.':'Percorra finalidade, apoio, condução e revisão. Escolha os recursos e confira o que acontecerá em cada momento.'}</p></div><button class="s-profile-shot" data-gallery-file="${s.file}" data-gallery-product="studio-profiles" aria-label="Ampliar ${s.type}"><span class="s-profile-window"><i></i><i></i><i></i><small>${i?'Preparar com IA':'Configuração guiada'} / Ampliar ↗</small></span><img src="/assets/screens/${s.file}" alt="${ce(s.title)}" width="1280" height="800" loading="lazy"></button><div class="s-profile-footer"><span>${i?'Você aprova antes de criar.':'Você escolhe o que configurar.'}</span><a href="${s.source}" target="_blank" rel="noopener">Origem / 20.10.2026 ↗</a></div></article>`).join('')}</div><div class="s-profile-moments"><div><span>Durante a conversa</span><p>O apoio e as sugestões seguem o propósito do perfil.</p></div><div><span>Ao encerrar</span><p>Resumo e ações são escolhidos conforme o atendimento.</p></div><div><span>Após a revisão</span><p>Os próximos passos respeitam as liberações definidas.</p></div></div><p class="s-profile-evidence">Capturas de validação de 20/10/2026, preservadas no repositório: formulário em prévia local e preparação com IA em candidato local de design. Mostram a configuração e a tela de entrada do assistente; não comprovam uma sessão de IA executada nem a publicação dessas interfaces em produção.</p></div></section>`}
